svg.script:
/* Pleine largeur (v1.2) : quand la zone d'affichage est plus large que le format 1366 × 704,
   on élargit la viewBox au même format qu'elle (la hauteur reste 704 : tout reste visible, sans
   ascenseur) et on écarte chaque élément selon la position de son centre, sans le déformer. */
(function () {
  var racine = document.documentElement, W0 = 1366, H0 = 704, C = W0 / 2;
  function $(s) { return document.querySelector(s); }
  function attr(el, n) { return el.getAttribute(n); }
  var maths = $("#maths"), galaxie = $("#galaxie"), cellule = $("#cellule"),
      filsMG = $("#fils-maths-galaxie"), poussiere = $("#poussiere-cellule"),
      cadre = $("rect[x='94']"), schema = $(".schema-qft"), degrade = $("#degrade-symetries"),
      filet = $("line[x1='790']"), phrase = filet ? filet.nextElementSibling : null;
  var tMaths = attr(maths, "transform"), tGalaxie = attr(galaxie, "transform");
  var fils = [].slice.call(document.querySelectorAll("#fils-galaxie-cellule path")).map(function (p) {
    return { p: p, n: attr(p, "d").match(/-?\d+(?:\.\d+)?/g).map(Number) };
  });
  var legendes = [].slice.call(document.querySelectorAll(".legendes > *")).map(function (el) {
    var x = Number(attr(el, "cx") || attr(el, "x") || attr(el, "x1"));
    var ancre = [272, 700, 1128].reduce(function (a, b) { return Math.abs(b - x) < Math.abs(a - x) ? b : a; });
    return { el: el, ancre: ancre };
  });
  var echelleSchema = 610 / 660;                       /* le bandeau QFT est un svg imbriqué réduit */
  var colonnes = [[".qft-ancien", 130], [".qft-bascule", 330], [".qft-nouveau", 530]].map(function (c) {
    return { el: schema.querySelector(c[0]), ancre: 140 + c[1] * echelleSchema };
  });
  if (schema) schema.setAttribute("overflow", "visible");

  function appliquer() {
    var w = window.innerWidth, h = window.innerHeight;
    if (!w || !h) return;
    var W = Math.max(W0, H0 * w / h), e = (W - W0) / 2, k = W / W0;
    function f(x) { return C + (x - C) * k; }          /* position écartée d'un centre */
    function d(x) { return f(x) - x; }                 /* décalage correspondant */
    function tr(dx) { return "translate(" + dx.toFixed(2) + " 0)"; }

    racine.setAttribute("viewBox", (-e).toFixed(2) + " 0 " + W.toFixed(2) + " " + H0);

    /* Bandeau : cadre élargi, colonnes et phrase écartées */
    cadre.setAttribute("x", f(94).toFixed(2));
    cadre.setAttribute("width", (f(1272) - f(94)).toFixed(2));
    colonnes.forEach(function (c) { if (c.el) c.el.setAttribute("transform", tr(d(c.ancre) / echelleSchema)); });
    if (filet) filet.setAttribute("transform", tr(d(1010)));
    if (phrase) phrase.setAttribute("transform", tr(d(1010)));

    /* Trois motifs */
    maths.setAttribute("transform", tr(d(272)) + " " + tMaths);
    galaxie.setAttribute("transform", tr(d(700)) + " " + tGalaxie);
    cellule.setAttribute("transform", "translate(" + f(1128).toFixed(2) + " 425) scale(.8)");
    poussiere.setAttribute("transform", tr(d(1128)));

    /* Fils mathématiques → galaxie : étirés entre les deux motifs */
    var g = 410 + d(272), dr = 590 + d(700), s = (dr - g) / 180;
    filsMG.setAttribute("transform", "translate(" + g.toFixed(2) + " 0) scale(" + s.toFixed(4) + " 1) translate(-410 0)");

    /* Fils galaxie → cellule : la courbe s'étire, la boucle autour de la cellule suit la cellule */
    fils.forEach(function (o) {
      var n = o.n, a = 812 + d(700), b = n[6] + d(1128);
      function x(v) { return (a + (v - 812) * (b - a) / (n[6] - 812)).toFixed(1); }
      o.p.setAttribute("d", "M " + x(n[0]) + " " + n[1] + " C " + x(n[2]) + " " + n[3] + ", " + x(n[4]) + " " + n[5] +
        ", " + b.toFixed(1) + " " + n[7] + " A " + n[8] + " " + n[9] + " " + n[10] + " " + n[11] + " " + n[12] +
        " " + (n[13] + d(1128)).toFixed(1) + " " + n[14]);
    });

    /* Légendes sous chaque motif */
    legendes.forEach(function (o) { o.el.setAttribute("transform", tr(d(o.ancre))); });
    if (degrade) { degrade.setAttribute("x1", 610 + d(700)); degrade.setAttribute("x2", 790 + d(700)); }
  }
  window.addEventListener("resize", appliquer);
  appliquer();
})();

/* v1.3 : les trois motifs en 3D */
/* QuantumSite : les 3 motifs de l'accueil en 3D (SVG + petit moteur de projection, sans bibliothèque). */
(function(){
const F=600, D=600, NS='http://www.w3.org/2000/svg';
const RM = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
const f1=v=>Math.round(v*10)/10;
const L=(()=>{const v=[-.45,.75,.55],n=Math.hypot(...v);return v.map(a=>a/n)})();

function rot(p,c){const x1=p[0]*c.cy+p[2]*c.sy, z1=-p[0]*c.sy+p[2]*c.cy;return [x1,p[1]*c.cp-z1*c.sp,p[1]*c.sp+z1*c.cp];}
function proj(v,c){const s=F/(D-v[2]);return [c.x+v[0]*s,c.y-v[1]*s,s];}
const pts=P=>P.map(p=>f1(p[0])+','+f1(p[1])).join(' ');
function mix(a,b,k){return 'rgb('+a.map((v,i)=>Math.round(v+(b[i]-v)*k)).join(',')+')';}

/* primitives */
function ring(r,y,n,a0,a1,fn){const o=[];for(let i=0;i<=n;i++){const a=a0+(a1-a0)*i/n;o.push(fn?fn(r,a):[r*Math.cos(a),y,r*Math.sin(a)]);}return o;}
function segs(P,st,k){const o=[];k=k||1;for(let i=0;i<P.length-1;i+=k)o.push(Object.assign({t:'l',p:P.slice(i,Math.min(i+k,P.length-1)+1)},st));return o;}
function box(x,z,w,h,y0,col,alpha,edge){
  const a=w/2,y1=y0+h,o=[];
  const V=(dx,dy,dz)=>[x+dx,dy,z+dz];
  const faces=[
    [[0,1,0],[V(-a,y1,-a),V(a,y1,-a),V(a,y1,a),V(-a,y1,a)]],
    [[1,0,0],[V(a,y0,-a),V(a,y0,a),V(a,y1,a),V(a,y1,-a)]],
    [[-1,0,0],[V(-a,y0,-a),V(-a,y1,-a),V(-a,y1,a),V(-a,y0,a)]],
    [[0,0,1],[V(-a,y0,a),V(-a,y1,a),V(a,y1,a),V(a,y0,a)]],
    [[0,0,-1],[V(-a,y0,-a),V(a,y0,-a),V(a,y1,-a),V(-a,y1,-a)]]];
  for(const [n,p] of faces)o.push({t:'f',p,n,col,alpha,edge,top:n[1]===1});
  return o;
}

function Scene(svg,cfg){
  this.svg=svg;this.cfg=cfg;this.yaw=0;this.uy=0;this.up=0;this.hy=0;this.hp=0;this.thy=0;this.thp=0;
  this.g=document.createElementNS(NS,'g');svg.appendChild(this.g);
  if(cfg.over){const o=document.createElementNS(NS,'g');o.innerHTML=cfg.over;svg.appendChild(o);}
  this.static=cfg.build();
  let drag=null;this.moved=false;
  svg.style.touchAction='pan-y';svg.style.cursor='grab';
  svg.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,uy:this.uy,up:this.up};this.moved=false;svg.style.cursor='grabbing';});
  window.addEventListener('pointerup',()=>{if(drag){drag=null;svg.style.cursor='grab';}});
  svg.addEventListener('pointermove',e=>{
    const r=svg.getBoundingClientRect();
    if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)this.moved=true;
      this.uy=drag.uy+dx*.012;this.up=Math.max(-.35,Math.min(.5,drag.up+dy*.006));}
    else{this.thy=((e.clientX-r.left)/r.width-.5)*.7;this.thp=((e.clientY-r.top)/r.height-.5)*.35;}
  });
  svg.addEventListener('pointerleave',()=>{this.thy=0;this.thp=0;});
  svg.addEventListener('click',e=>{if(this.moved){e.stopPropagation();e.preventDefault();this.moved=false;}},true);
}
Scene.prototype.frame=function(t){
  const c=this.cfg;
  this.hy+=(this.thy-this.hy)*.08;this.hp+=(this.thp-this.hp)*.08;
  const yaw=(RM?0:c.auto(t))+this.uy+this.hy+(c.yaw0||0), pit=c.pitch+this.up+this.hp;
  const C={cy:Math.cos(yaw),sy:Math.sin(yaw),cp:Math.cos(pit),sp:Math.sin(pit),x:c.cx,y:c.cy};
  const prims=this.static.concat(c.dyn?c.dyn(RM?0:t):[]);
  const items=[];
  for(const pr of prims){
    const V=pr.p.map(p=>rot(p,C));
    let d=0;for(const v of V)d+=v[2];d/=V.length;d+=(pr.b||0);
    let k=1;
    if(pr.n){const n=rot(pr.n,C),cx=V.reduce((s,v)=>s+v[0],0)/V.length,cy=V.reduce((s,v)=>s+v[1],0)/V.length,cz=V.reduce((s,v)=>s+v[2],0)/V.length;
      if(n[0]*(0-cx)+n[1]*(0-cy)+n[2]*(D-cz)<=0)continue;
      k=Math.max(0,n[0]*L[0]+n[1]*L[1]+n[2]*L[2]);}
    items.push({pr,V,d,k});
  }
  items.sort((a,b)=>a.d-b.d);
  let o='';
  for(const it of items){
    const pr=it.pr,P=it.V.map(v=>proj(v,C));
    if(pr.t==='f'){
      const fill=pr.top?mix(pr.col,[255,255,255],.35+.4*it.k):mix([4,20,40],pr.col,.35+.65*it.k);
      o+=`<polygon points="${pts(P)}" fill="${fill}" fill-opacity="${pr.alpha}"${pr.edge?` stroke="${pr.edge}" stroke-width=".7" stroke-opacity=".8"`:''} stroke-linejoin="round"/>`;
    }else if(pr.t==='poly'){
      o+=`<polygon points="${pts(P)}" fill="${pr.fill}"${pr.op!=null?` opacity="${pr.op}"`:''}${pr.s?` stroke="${pr.s}" stroke-opacity="${pr.so||1}"`:''}/>`;
    }else if(pr.t==='l'){
      const s=P[0][2];
      o+=`<polyline points="${pts(P)}" fill="none" stroke="${pr.s}" stroke-opacity="${pr.o==null?1:pr.o}" stroke-width="${f1((pr.w||1)*s*100)/100}" stroke-linecap="round"${pr.da?` stroke-dasharray="${pr.da}"`:''}${pr.fl?` filter="url(#${pr.fl})"`:''}/>`;
    }else if(pr.t==='b'){
      const p=P[0],r=f1(pr.r*p[2]);
      o+=`<circle cx="${f1(p[0])}" cy="${f1(p[1])}" r="${r}" fill="${pr.fill}"${pr.s?` stroke="${pr.s}" stroke-width="${pr.sw||1.5}"`:''}${pr.op!=null?` opacity="${pr.op}"`:''}${pr.fl?` filter="url(#${pr.fl})"`:''}/>`;
      if(pr.lab)o+=`<text x="${f1(p[0])}" y="${f1(p[1]+4*p[2])}" font-size="${f1(11*p[2])}" fill="${pr.lc||'#ffe0e7'}"${pr.lw?` font-weight="${pr.lw}"`:''} text-anchor="middle" font-family="JetBrains Mono,monospace">${pr.lab}</text>`;
    }else if(pr.t==='cap'){
      const s=(P[0][2]+P[1][2])/2,ln=pts(P);
      o+=`<polyline points="${ln}" stroke="${pr.c1}" stroke-width="${f1(pr.r*2*s)}" stroke-linecap="round" fill="none"/><polyline points="${ln}" stroke="${pr.c2}" stroke-width="${f1(pr.r*1.3*s)}" stroke-linecap="round" fill="none" opacity=".8"/>`;
      const n=pr.k||5,ax=P[1][0]-P[0][0],ay=P[1][1]-P[0][1],L2=Math.hypot(ax,ay)||1,nx=-ay/L2,ny=ax/L2,w=pr.r*.75*s;let z='';
      for(let i=0;i<=n*2;i++){const t=i/(n*2),sg=i%2?1:-1;z+=f1(P[0][0]+ax*t+nx*w*sg)+','+f1(P[0][1]+ay*t+ny*w*sg)+' ';}
      o+=`<polyline points="${z}" stroke="${pr.c3}" stroke-width="${f1(1.1*s)}" fill="none" stroke-linejoin="round" opacity=".85"/>`;
    }else if(pr.t==='tx'){
      const p=P[0];
      o+=`<text x="${f1(p[0])}" y="${f1(p[1])}" font-size="${f1(pr.fs*p[2])}" fill="${pr.fill}" text-anchor="${pr.a||'middle'}" font-family="${pr.ff||'Jost,sans-serif'}"${pr.fw?` font-weight="${pr.fw}"`:''}${pr.op!=null?` opacity="${pr.op}"`:''}>${pr.s}</text>`;
    }
  }
  this.g.innerHTML=o;
};


let SEED=7;const rnd=()=>{SEED|=0;SEED=SEED+0x6D2B79F5|0;let t=Math.imul(SEED^SEED>>>15,1|SEED);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};
const gau=()=>{let u=0,v=0;while(!u)u=rnd();while(!v)v=rnd();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);};
const tilt=(p,ax,ay)=>{let[x,y,z]=p;const y1=y*Math.cos(ax)-z*Math.sin(ax),z1=y*Math.sin(ax)+z*Math.cos(ax);return[x*Math.cos(ay)+z1*Math.sin(ay),y1,-x*Math.sin(ay)+z1*Math.cos(ay)];};

/* ---------- 1. Les mathématiques : noyau, orbites, rectangle d'or ---------- */
const ORB=[0,Math.PI/3,2*Math.PI/3].map(ay=>({ax:1.2,ay}));
function samplePath(d,n){const s=document.createElementNS(NS,'svg');s.setAttribute('style','position:absolute;width:0;height:0');const p=document.createElementNS(NS,'path');p.setAttribute('d',d);s.appendChild(p);document.documentElement.appendChild(s);const L=p.getTotalLength(),o=[];for(let i=0;i<=n;i++){const q=p.getPointAtLength(L*i/n);o.push([q.x,q.y]);}s.remove();return o;}
function maths(){
  const o=[],W='#f2fbff',M=(x,y)=>[(x-266)*.74,-(y-448)*.74,0];
  o.push({t:'b',p:[[0,0,0]],r:68,fill:'url(#qNoyau)'});
  for(const la of [-.6,0,.6]){const r=78*Math.cos(la),y=78*Math.sin(la);o.push(...segs(ring(r,y,40,0,2*Math.PI),{s:W,o:.22,w:.8},2));}
  for(let k=0;k<4;k++){const a=k*Math.PI/4,P=[];for(let i=0;i<=40;i++){const b=i/40*2*Math.PI;P.push([78*Math.cos(b)*Math.cos(a),78*Math.sin(b),78*Math.cos(b)*Math.sin(a)]);}o.push(...segs(P,{s:W,o:.16,w:.7},2));}
  for(const q of ORB)o.push(...segs(ring(112,0,64,0,2*Math.PI).map(p=>tilt(p,q.ax,q.ay)),{s:W,o:.75,w:1.1},2));
  const R=[[130,363.9,402,363.9],[402,363.9,402,532.1],[402,532.1,130,532.1],[130,532.1,130,363.9],[298.1,363.9,298.1,532.1],[298.1,467.8,402,467.8],[337.8,467.8,337.8,532.1],[298.1,492.4,337.8,492.4],[322.6,467.8,322.6,492.4],[322.6,483,337.8,483],[328.4,483,328.4,492.4]];
  R.forEach(([x1,y1,x2,y2],i)=>{const n=Math.max(1,Math.round(Math.hypot(x2-x1,y2-y1)/20)),P=[];for(let j=0;j<=n;j++)P.push(M(x1+(x2-x1)*j/n,y1+(y2-y1)*j/n));o.push(...segs(P,{s:W,o:.95,w:i<4?1.6:1.2}));});
  const sp=samplePath('M 130.0 532.1 A 168.1 168.1 0 0 1 298.1 363.9 A 103.9 103.9 0 0 1 402.0 467.8 A 64.2 64.2 0 0 1 337.8 532.1 A 39.7 39.7 0 0 1 298.1 492.4 A 24.5 24.5 0 0 1 322.6 467.8 A 15.2 15.2 0 0 1 337.8 483.0 A 9.4 9.4 0 0 1 328.4 492.4',90).map(([x,y])=>M(x,y));
  o.push(...segs(sp,{s:'#ffffff',o:1,w:3,fl:'qLueur'},3));
  const sup=(a,b,c)=>`${a}<tspan dy="-4" font-size="70%">${b}</tspan><tspan dy="4">${c}</tspan>`;
  const F=[['φ = (1+√5)/2',[-110,118,20]],['Fₙ₊₁/Fₙ → φ',[96,122,-30]],['Σ 1/n² = π²/6',[-128,62,-40]],['− log φ ≈ −0,481',[80,58,60]],[sup('e','iπ',' + 1 = 0'),[-96,8,70]],['√2 ≈ 1,414',[140,4,-20]],[sup('∫ e','−x²',' dx = √π'),[-104,-84,30]],['∇·E = ρ/ε₀',[96,-46,40]],['a² + b² = c²',[-14,-122,-20]],['π ≈ 3,1416',[-150,-30,-30]]];
  for(const [s,p] of F)o.push({t:'tx',p:[p],s,fs:10,fill:'#d8f3ff',op:.85});
  return o;
}
function mathsDyn(t){
  return ORB.map((q,i)=>{const a=t*(.9+i*.25)+i*2.1;return {t:'b',p:[tilt([112*Math.cos(a),0,112*Math.sin(a)],q.ax,q.ay)],r:3.6,fill:'#ffffff',fl:'qLueur'};});
}

/* ---------- 2. Les symétries : la galaxie spirale ---------- */
SEED=11;
const GCOL=['#fff4d0','#ffffff','#cfefff','#9edcff','#6fc4ff','#b8a8ff','#d7c8ff'];
const GAL=[];
for(let i=0;i<1100;i++){
  const bulge=i<220,r=bulge?Math.abs(gau())*24:14+140*Math.pow(rnd(),.9),arm=rnd()<.5?0:Math.PI;
  const th=bulge?rnd()*2*Math.PI:arm+Math.log(r/14)/.34+gau()*(rnd()<.15?.7:.16);
  const y=bulge?gau()*20:gau()*(3+9*(1-r/165));
  const ci=bulge?(rnd()<.6?0:1):Math.min(6,Math.floor(r/165*5+rnd()*2.2));
  GAL.push({r,th,y,c:GCOL[ci],s:.5+rnd()*1.5*(bulge?1.2:1),o:.45+rnd()*.55});
}
for(let i=0;i<320;i++){let x,y,z;do{x=gau()*60;y=gau()*60;z=gau()*60;}while(Math.hypot(x,y,z)>150);const r=Math.hypot(x,z);GAL.push({r,th:Math.atan2(z,x),y,c:GCOL[1+Math.floor(rnd()*6)],s:.4+rnd()*1.1,o:.25+rnd()*.5});}
const ARMS=[0,Math.PI].map(a=>{const P=[];for(let r=16;r<=155;r+=6)P.push([r,a+Math.log(r/14)/.34]);return P;});
function galaxie(){return [];}
function galDyn(t){
  const w=t*.14,o=[{t:'b',p:[[0,0,0]],r:66,fill:'url(#qNoyauGal)'}];
  for(const A of ARMS){const P=A.map(([r,a])=>[r*Math.cos(a+w),0,r*Math.sin(a+w)]);o.push(...segs(P,{s:'#6fc4ff',o:.45,w:12,fl:'qFlou'},5));o.push(...segs(P,{s:'#9edcff',o:.25,w:1.2},5));}
  for(const g of GAL){const a=g.th+w;o.push({t:'b',p:[[g.r*Math.cos(a),g.y,g.r*Math.sin(a)]],r:g.s,fill:g.c,op:g.o});}
  o.push({t:'b',p:[[0,0,0]],r:14,fill:'#ffffff',fl:'qLueur',b:1});
  return o;
}

/* ---------- 3. La géométrie : la cellule en volume ---------- */
SEED=5;
const RC=124,NUC=[-14,6,-4];
function cellule(){
  const o=[],C='#ff8f9c';
  for(const la of [-1.1,-.7,-.35,0,.35,.7,1.1]){const r=RC*Math.cos(la),y=RC*Math.sin(la);o.push(...segs(ring(r,y,48,0,2*Math.PI),{s:C,o:.13,w:.8},3));}
  for(let k=0;k<6;k++){const a=k*Math.PI/6,P=[];for(let i=0;i<=48;i++){const b=i/48*2*Math.PI;P.push([RC*Math.cos(b)*Math.cos(a),RC*Math.sin(b),RC*Math.cos(b)*Math.sin(a)]);}o.push(...segs(P,{s:C,o:.11,w:.8},3));}
  o.push({t:'b',p:[NUC],r:40,fill:'url(#qNoyauCell)',s:'#ffa3ae',sw:1.2});
  o.push({t:'b',p:[[NUC[0]+8,NUC[1]+6,NUC[2]+22]],r:12,fill:'url(#qNucleole)',b:2});
  for(let i=0;i<34;i++){const u=rnd()*2-1,a=rnd()*2*Math.PI,s=Math.sqrt(1-u*u);o.push({t:'b',p:[[NUC[0]+41*s*Math.cos(a),NUC[1]+41*u,NUC[2]+41*s*Math.sin(a)]],r:1.5,fill:'#ffe0e4',op:.8});}
  [56,66,76].forEach((r,k)=>{const P=[];for(let i=0;i<=40;i++){const a=-1.25+2.6*i/40;P.push([NUC[0]+r*Math.cos(a),NUC[1]+r*Math.sin(a)*.95,NUC[2]+16*Math.sin(3*a+k)]);}
    for(let i=0;i<P.length-1;i+=2){const Q=P.slice(i,i+3);o.push({t:'l',p:Q,s:C,o:.75,w:5,fl:'qLueur'},{t:'l',p:Q,s:'#4a0a16',o:.9,w:1.6,b:.2});}
    for(let i=1;i<P.length;i+=3)o.push({t:'b',p:[[P[i][0]+4,P[i][1]-3,P[i][2]]],r:1.6,fill:'#ffd0d6',b:.3});});
  const G=[-72,-52,34];
  [20,26,32,38].forEach((r,k)=>{const P=[];for(let i=0;i<=12;i++){const a=2.1+1.9*i/12;P.push([G[0]+r*Math.cos(a)+30,G[1]+r*Math.sin(a)*.8+20,G[2]+k*5]);}o.push(...segs(P,{s:'#ffc2c9',o:.9,w:3.4},3));o.push({t:'b',p:[P[0]],r:2.6,fill:'#ffc2c9'},{t:'b',p:[P[12]],r:2.6,fill:'#ffc2c9'});});
  const MI=[[62,-58,30,.6,.2],[76,40,-30,-.3,1.1],[-62,62,40,1.2,.3],[-80,-20,-50,.2,-.9],[20,-88,-40,-.9,.4],[30,78,58,.4,1.4],[-30,-70,-70,1.4,.8]];
  for(const [x,y,z,a,b] of MI){const d=tilt([16,0,0],a,b);o.push({t:'cap',p:[[x-d[0],y-d[1],z-d[2]],[x+d[0],y+d[1],z+d[2]]],r:8,c1:'#ff6a3d',c2:'#ffb09a',c3:'#8a1c0c',k:5});}
  for(let i=0;i<16;i++){let p;do{p=[gau()*55,gau()*55,gau()*55];}while(Math.hypot(...p)>108||Math.hypot(p[0]-NUC[0],p[1]-NUC[1],p[2]-NUC[2])<50);o.push({t:'b',p:[p],r:3+rnd()*3,fill:'url(#qBulle)'});}
  for(let i=0;i<150;i++){let p;do{p=[(rnd()*2-1)*118,(rnd()*2-1)*118,(rnd()*2-1)*118];}while(Math.hypot(...p)>118);o.push({t:'b',p:[p],r:1.1,fill:'#ffb3bc',op:.35+rnd()*.5});}
  return o;
}

const DEFS={
maths:`<radialGradient id="qNoyau"><stop offset="0" stop-color="#ffffff"/><stop offset=".25" stop-color="#7ff0ff"/><stop offset=".6" stop-color="#1bb8e0" stop-opacity=".5"/><stop offset="1" stop-color="#1bb8e0" stop-opacity="0"/></radialGradient>`,
galaxie:`<radialGradient id="qNoyauGal"><stop offset="0" stop-color="#ffffff"/><stop offset=".18" stop-color="#fff2c2"/><stop offset=".45" stop-color="#f0c879" stop-opacity=".55"/><stop offset="1" stop-color="#7fb8d8" stop-opacity="0"/></radialGradient>
<filter id="qFlou" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="4"/></filter>`,
cellule:`<radialGradient id="qNoyauCell" cx=".38" cy=".34" r=".75"><stop offset="0" stop-color="#ffd0d6"/><stop offset=".45" stop-color="#ff4d5e"/><stop offset="1" stop-color="#6a0f20"/></radialGradient>
<radialGradient id="qNucleole" cx=".4" cy=".35"><stop offset="0" stop-color="#ffe0e4"/><stop offset=".6" stop-color="#ff7080"/><stop offset="1" stop-color="#8a1030"/></radialGradient>
<radialGradient id="qBulle" cx="40%" cy="38%"><stop offset="0" stop-color="#ffe0e0"/><stop offset=".35" stop-color="#ff6b7a"/><stop offset="1" stop-color="#9a2a3a" stop-opacity=".2"/></radialGradient>`};
const LUEUR='<filter id="qLueur" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur in="SourceGraphic" stdDeviation="3" result="f"/><feMerge><feMergeNode in="f"/><feMergeNode in="SourceGraphic"/></feMerge></filter>';
const CFG={
  maths:{build:maths,dyn:mathsDyn,pitch:.22,cx:180,cy:180,auto:t=>.65*Math.sin(t*.3)},
  galaxie:{build:galaxie,dyn:galDyn,pitch:1.2,cx:180,cy:180,auto:t=>.25*Math.sin(t*.15)},
  cellule:{build:cellule,pitch:.3,cx:180,cy:180,auto:t=>t*.16}
};
const scenes=[];
document.querySelectorAll('svg[data-3d]').forEach(svg=>{
  const k=svg.getAttribute('data-3d');
  const d=document.createElementNS(NS,'defs');d.innerHTML=DEFS[k]+(svg.querySelector('#qLueur')?'':LUEUR);svg.insertBefore(d,svg.firstChild);
  scenes.push(new Scene(svg,CFG[k]));
});
const t0=performance.now();let vis=true;
document.addEventListener('visibilitychange',()=>{vis=!document.hidden;});
function loop(now){if(vis){const t=Math.max(0,(now-t0)/1000);for(const s of scenes){const r=s.svg.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)s.frame(t);}}requestAnimationFrame(loop);}
scenes.forEach(s=>s.frame(0));requestAnimationFrame(loop);
})();
